from lib import *
S = SS('t32')
steps = [
    step("先量没有失败时拆分的代价。400 个订单单线程顺序下单,没有临时失败,也没有余额不足的订单。单体(一个库、一个本地事务):延迟中位数 0.22 ms,p99 0.65 ms,每单 1 次提交。拆成三个库各自提交、没有保护:0.45 ms,p99 1.03 ms,3 次提交。拆成三个库 + XA:0.82 ms,p99 1.97 ms,3 次分支提交。拆成三个库 + Saga(状态表 + 补偿 + 重试):0.56 ms,p99 0.72 ms,4 次提交。订单与库存合并成一个库、只有支付在另一个库:0.40 ms,p99 0.56 ms,3 次提交。拆得越多,每单要多等几次往返和提交;XA 的中位数是单体的 0.82 ÷ 0.22 ≈ 3.7 倍(算出来的比值)。", t=tl(S(1)), mark=lidx(S(1), '拆成三个库 + XA'), done=lidx(S(1), '单体:一个库'), b=bars([['单体 中位数 ms', 0.22, '0.22'], ['朴素拆分 中位数 ms', 0.45, '0.45'], ['XA 中位数 ms', 0.82, '0.82'], ['Saga 中位数 ms', 0.56, '0.56'], ['订单+库存合并 中位数 ms', 0.40, '0.40']], 0.82, done=[0], mark=[2], cur=[1, 3, 4]), kv=KV([['单体', '0.22 ms,1 次提交'], ['XA', '0.82 ms,p99 1.97 ms'], ['Saga', '0.56 ms,4 次提交'], ['合并订单+库存', '0.40 ms']], ['XA'])),
    step("再看 8 个线程并发下单(每个线程 100 单,没有失败),3 轮取中位数。单体 4901 单/秒(3 轮范围 4614 到 4958),定为 1.00x。朴素拆分 3111 单/秒(2626 到 3857),0.63x。XA 1306 单/秒(1294 到 1319),0.27x。Saga 2982 单/秒(2945 到 3020),0.61x。订单与库存合并 3846 单/秒(2567 到 4008),0.78x,3 轮之间抖动大,范围从 2567 到 4008,这一行只能说比 Saga 略快,不能说精确是 0.78。XA 在并发下只有单体的四分之一左右。", t=tl(S(2)), mark=lidx(S(2), '拆成三个库 + XA'), done=lidx(S(2), '单体:一个库'), b=bars([['单体 单/秒', 4901, '4901'], ['朴素拆分 单/秒', 3111, '3111'], ['XA 单/秒', 1306, '1306'], ['Saga 单/秒', 2982, '2982'], ['订单+库存合并 单/秒', 3846, '3846(范围 2567~4008)']], 4901, done=[0], mark=[2], cur=[1, 3, 4]), kv=KV([['XA', '1306 单/秒,0.27x'], ['Saga', '2982 单/秒,0.61x'], ['合并订单+库存', '3846 单/秒,抖动大'], ['单体', '4901 单/秒']], ['XA'])),
    step("加上失败:2000 个订单单线程,每次远程调用 3% 临时失败,2% 的订单金额超过余额,五种实现面对的失败完全相同。单体:下单成功 1959,业务拒绝 41,失败 0,库里只有 1959 个订单的记录,对账全是 0。朴素拆分:成功 1851,拒绝 37,失败 112,库里有 2000 个订单的记录,其中订单已确认却缺库存预留或扣款的有 149 个。XA:1959 / 41 / 0,记录 1959,对账 0。Saga:1959 / 41 / 0,记录 2000(补偿过的订单留着痕迹),已确认缺项 0、泄漏 0、停在 PENDING 0。订单与库存合并:1959 / 41 / 0,对账 0。Saga 里补偿重试用完仍没释放库存、卡住的有 0 个,这次没有注入恢复扫描要处理的情形,不能说明生产里不会卡住。", t=tl(S(3)), mark=lidx(S(3), '各自提交,没有保护'), done=lidx(S(3), '单体:一个库', '+ XA(两阶段提交)', '+ Saga(状态表', '订单与库存合并成一个库'), b=bars([['朴素拆分 失败的订单', 112, '112'], ['朴素拆分 已确认缺项', 149, '149'], ['XA 对账不一致', 0, '0'], ['Saga 对账不一致', 0, '0'], ['合并 对账不一致', 0, '0']], 149, mark=[0, 1], done=[2, 3, 4]), kv=KV([['朴素拆分', '失败 112,已确认却缺预留或扣款 149'], ['XA / Saga / 合并', '对账不一致 0'], ['Saga 代价', '中间状态对外可见一小段时间'], ['Saga 卡住', '0 个(未模拟恢复场景)']], ['朴素拆分'])),
    step("最后数代码量和额外依赖(只是本实验里这几个函数的写法,不是任何框架的真实工作量)。单体 14 行有效代码,1 个库,没有额外的表。朴素拆分 10 行,3 个库,没有额外的表,也没有保护。XA 29 行,要数据库支持 XA,prepared 事务要有人收尾。Saga 44 行,多一张 saga_log 表和重试 / 补偿逻辑,生产里还需要恢复守护进程和对账。订单与库存合并 24 行,2 个库,只有支付一步需要重试 / 补偿。每多拆一个库,就多写一段“这一步失败怎么办”;把总是一起改的订单和库存放进同一个库,Saga 就只剩支付一步,代码从 44 行降到 24 行,对账同样是 0。", t=tl(S(4)), mark=lidx(S(4), 'Saga      |'), done=lidx(S(4), '订单 + 库存合并'), b=bars([['单体 行', 14, '14'], ['朴素拆分 行', 10, '10'], ['XA 行', 29, '29'], ['Saga 行', 44, '44'], ['订单+库存合并 行', 24, '24'], ], 44, mark=[3], done=[4], cur=[0, 1, 2]), kv=KV([['Saga', '44 行 + saga_log + 恢复 + 对账'], ['XA', '29 行 + 要有人收尾 prepared'], ['订单+库存合并', '24 行,只剩支付一步'], ['单体', '14 行']], ['订单+库存合并'])),
]
A = mkartt('t32', 32, '分布式事务,业务拆分,事务边界,XA,Saga,MySQL,真实验证,动画演示',
    '同一个下单业务的五种实现:单体、朴素拆分、XA、Saga、订单与库存合并。没有失败时 XA 并发只有单体的 0.27x;有 3% 临时失败时朴素拆分留下 149 个订单已确认却缺项,XA、Saga、合并版对账为 0;合并订单与库存后代码从 44 行降到 24 行。',
    '什么时候该拆、什么时候别拆?这篇把“建订单 + 扣库存 + 扣余额”做成五种实现,跑在 4 个独立的 MySQL 上,同样的失败、同样的订单,量出延迟、吞吐、对账结果和代码量,看拆分的代价到底落在哪里。',
    [('0.27x', '8 线程并发下单,三个库 + XA 的吞吐相对单体(1306 对 4901 单/秒)'), ('149 / 2000', '朴素拆分在 3% 临时失败下,订单已确认却缺库存预留或扣款的订单数'), ('44 → 24', '把总是一起改的订单和库存合并成一个库后,下单函数的有效代码行数(Saga → 合并)')],
    [('没有失败时的代价', '<p>拆得越多,每单要多几次往返和提交;XA 的中位延迟约为单体的 3.7 倍(0.82 ms 对 0.22 ms 算出的比值),Saga 多一次状态表提交。</p>'),
     ('并发下的吞吐', '<p>XA 并发只有单体的约四分之一,Saga 约六成;合并订单与库存的版本介于 Saga 与单体之间,但这一行抖动很大。</p>'),
     ('有失败时的结果', '<p>朴素拆分留下 149 个对不上的订单;XA 靠整体回滚、Saga 靠补偿、合并版靠本地事务,对账都是 0,代价各不相同。</p>'),
     ('代码量与组件', '<p>每多拆一个库就要多写一段“失败怎么办”。能放进同一个本地事务的,就不要拆开去补偿。</p>')],
    steps,
    [ENV_T + '。本篇用四个独立的 MySQL 26.7.0 实例(单体库、订单库、库存库、钱包库),PyMySQL 客户端,每个线程每个库一个连接;失败按订单号的 crc32 确定地注入(每次远程调用 3% 临时失败,在调用执行之前就失败;2% 的订单金额超过余额),五种实现遇到完全相同的失败;XA 与 Saga 是我手写的实现,不是任何框架;代码行数是这几个函数在本实验里的写法',
     '没有验证:真实网络里的延迟与超时(四个实例在同一台机器上,往返极小,拆分的真实代价会更大);XA 的失败恢复(prepared 事务在协调者崩溃后的收尾,见第 3、5 篇);Saga 补偿本身反复失败后的恢复(这次补偿重试没有用完,卡住是 0,恢复守护进程见第 30 篇);更多线程、更大数据量下的比较(并发只测了 8 线程,每个线程 100 单);并发下 Saga 与合并版的隔离问题(第 10 篇);团队、部署与组织层面的拆分理由(本篇只比较事务边界)'],
    '什么时候别拆')
